CREATE TABLE IF NOT EXISTS admin_users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS works (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('music','software','game','animation')),
  summary TEXT NOT NULL,
  detail_intro TEXT NOT NULL DEFAULT '',
  background TEXT NOT NULL,
  process TEXT NOT NULL,
  result TEXT NOT NULL,
  feature_list TEXT[] NOT NULL DEFAULT '{}',
  interaction_points TEXT[] NOT NULL DEFAULT '{}',
  gallery_images JSONB NOT NULL DEFAULT '[]'::jsonb,
  detail_sections JSONB NOT NULL DEFAULT '[]'::jsonb,
  platform TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT '',
  cover_url TEXT NOT NULL,
  demo_url TEXT,
  repo_url TEXT,
  published_at DATE NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE works ADD COLUMN IF NOT EXISTS detail_intro TEXT NOT NULL DEFAULT '';
ALTER TABLE works ADD COLUMN IF NOT EXISTS feature_list TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE works ADD COLUMN IF NOT EXISTS interaction_points TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE works ADD COLUMN IF NOT EXISTS gallery_images JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE works ADD COLUMN IF NOT EXISTS detail_sections JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE works ADD COLUMN IF NOT EXISTS platform TEXT NOT NULL DEFAULT '';
ALTER TABLE works ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT '';
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'works_type_check'
      AND conrelid = 'works'::regclass
  ) THEN
    ALTER TABLE works DROP CONSTRAINT works_type_check;
  END IF;
END $$;
ALTER TABLE works ADD CONSTRAINT works_type_check CHECK (type IN ('music','software','game','animation'));

CREATE TABLE IF NOT EXISTS reviews (
  id TEXT PRIMARY KEY,
  work_id TEXT NOT NULL REFERENCES works(id) ON DELETE CASCADE,
  rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment TEXT NOT NULL,
  visitor_name TEXT,
  owner_only BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS messages (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  contact TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','read','archived')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = 'admin_users'
      AND column_name = 'id'
      AND data_type = 'uuid'
  ) THEN
    ALTER TABLE admin_users ALTER COLUMN id TYPE TEXT USING id::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = 'works'
      AND column_name = 'id'
      AND data_type = 'uuid'
  ) THEN
    ALTER TABLE reviews DROP CONSTRAINT IF EXISTS reviews_work_id_fkey;
    ALTER TABLE works ALTER COLUMN id TYPE TEXT USING id::text;
    ALTER TABLE reviews ALTER COLUMN work_id TYPE TEXT USING work_id::text;
    ALTER TABLE reviews ADD CONSTRAINT reviews_work_id_fkey FOREIGN KEY (work_id) REFERENCES works(id) ON DELETE CASCADE;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = 'reviews'
      AND column_name = 'id'
      AND data_type = 'uuid'
  ) THEN
    ALTER TABLE reviews ALTER COLUMN id TYPE TEXT USING id::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = 'messages'
      AND column_name = 'id'
      AND data_type = 'uuid'
  ) THEN
    ALTER TABLE messages ALTER COLUMN id TYPE TEXT USING id::text;
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS pages (
  slug TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  hero TEXT NOT NULL,
  body TEXT NOT NULL,
  highlights TEXT[] NOT NULL DEFAULT '{}',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS site_settings (
  id TEXT PRIMARY KEY,
  site_title TEXT NOT NULL,
  tagline TEXT NOT NULL,
  primary_cta_label TEXT NOT NULL,
  primary_cta_href TEXT NOT NULL,
  secondary_cta_label TEXT NOT NULL,
  secondary_cta_href TEXT NOT NULL,
  banner_badge TEXT NOT NULL DEFAULT 'home-banner',
  banner_headline TEXT NOT NULL DEFAULT '',
  banner_description TEXT NOT NULL DEFAULT '',
  banner_image_url TEXT NOT NULL DEFAULT '',
  avatar_image_url TEXT NOT NULL DEFAULT '',
  afdian_url TEXT NOT NULL DEFAULT '',
  social_links JSONB NOT NULL DEFAULT '[]'::jsonb,
  music_preview_clips JSONB NOT NULL DEFAULT '[]'::jsonb,
  featured_work_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  ui_text JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS banner_badge TEXT NOT NULL DEFAULT 'home-banner';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS banner_headline TEXT NOT NULL DEFAULT '';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS banner_description TEXT NOT NULL DEFAULT '';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS banner_image_url TEXT NOT NULL DEFAULT '';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS avatar_image_url TEXT NOT NULL DEFAULT '';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS afdian_url TEXT NOT NULL DEFAULT '';
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS music_preview_clips JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS featured_work_ids JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS ui_text JSONB NOT NULL DEFAULT '{}'::jsonb;

